  "goals": [
    {
      "id": "g1",
      "actor": "Driver",
      "text": "Monitor the road and remain responsible for driving while Autopilot is active."
    },
    {
      "id": "g2",
      "actor": "Driver",
      "text": "Keep hands on the steering wheel while Autopilot is active."
    },
    {
      "id": "g3",
      "actor": "Autopilot",
      "text": "Provide Level 2 partial driving assistance without replacing the driver's responsibility."
    },
    {
      "id": "g4",
      "actor": "SensorSuite",
      "text": "Detect lane markings and objects ahead using the available camera, radar, and ultrasonic sensors."
    },
    {
      "id": "g5",
      "actor": "Autosteer",
      "text": "Keep the vehicle centered in its lane using lane markings and the vehicle ahead."
    },
    {
      "id": "g6",
      "actor": "TrafficAwareCruiseControl",
      "text": "Maintain the driver's set speed, slow for a vehicle ahead in the same lane, and speed up when the lane is clear."
    },
    {
      "id": "g7",
      "actor": "Driver",
      "text": "Use Autopilot in suitable conditions, particularly highways with limited access and good visibility."
    },
    {
      "id": "g8",
      "actor": "DriverMonitoring",
      "text": "Check for steering-wheel hands through steering torque and give visual and audible alerts when hands are not detected for a period."
    },
    {
      "id": "g9",
      "actor": "ForwardCollisionProtection",
      "text": "Provide forward collision warning and automatic emergency braking as separate available features."
    },
    {
      "id": "g10",
      "actor": "CarDrivers, TruckDrivers, Motorcyclists",
      "text": "Travel safely around other road users, including when cars are nearby and trucks cross or join the road."
    }
  ]
}

